const baseLat = parseFloat($json.base_lat);
const baseLng = parseFloat($json.base_lng);
let latIndex = parseInt($json.lat_index);
let lngIndex = parseInt($json.lng_index);

const step = 0.06;

// US bounds
const MIN_LAT = 25;
const MAX_LAT = 49;
const MIN_LNG = -125;
const MAX_LNG = -66;

// Calculate coordinates
let latitude = baseLat + (latIndex * step);
let longitude = baseLng + (lngIndex * step);

// 🔒 Fix longitude overflow (east/west)
if (longitude < MIN_LNG || longitude > MAX_LNG) {
  lngIndex = 0;
  latIndex += 1;
}

// 🔒 Fix latitude overflow (north/south)
if (latitude < MIN_LAT || latitude > MAX_LAT) {
  latIndex = 0;
}

// Recalculate after correction
latitude = baseLat + (latIndex * step);
longitude = baseLng + (lngIndex * step);

return [
{
  json: {
    latitude,
    longitude,
    latIndex,
    lngIndex,
    googleLocation: `${latitude},${longitude}`
  }
}
];

// Read state row from sheet
const state = $items("Get row(s) in sheet")[0].json;

// ---- SAFE STATE ----
let latIndex = Number(state.lat_index || 0);
let lngIndex = Number(state.lng_index || 0);

// 🔥 GUARANTEE DIRECTION EXISTS
let direction = Number(state.direction);
if (direction !== 1 && direction !== -1) {
  direction = 1;
}

// Optional (safe)
let dailyCount = Number(state.daily_count || 0);

// ---- BASE (DO NOT CHANGE IN SHEET) ----
const baseLat = Number(state.base_lat);
const baseLng = Number(state.base_lng);

// ---- CONFIG ----
const step = 0.06;
const eastLng = -66.06;
const northLat = 49;

// Max steps across from your base
const maxLngIndex = Math.floor((eastLng - baseLng) / step);

// ------------------------------------------------
// 🔥 MOVE FIRST (critical)
// ------------------------------------------------
if (direction === 1) {
  lngIndex += 1;
} else {
  lngIndex -= 1;
}

// ------------------------------------------------
// 🔥 EDGE HANDLING (ONLY place latitude changes)
// ------------------------------------------------

// Hit EAST edge
if (lngIndex >= maxLngIndex) {
  lngIndex = maxLngIndex;
  latIndex += 1;
  direction = -1;
}

// Hit WEST edge
else if (lngIndex <= 0) {
  lngIndex = 0;
  latIndex += 1;
  direction = 1;
}

// ------------------------------------------------
// CALCULATE POSITION
// ------------------------------------------------
const latitude = baseLat + (latIndex * step);
const longitude = baseLng + (lngIndex * step);

// Stop/reset at north
if (latitude >= northLat) {
  latIndex = 0;
  lngIndex = 0;
  direction = 1;
}

// ------------------------------------------------
// 🔥 ALWAYS RETURN CLEAN STATE
// ------------------------------------------------
return [
{
  json: {
    lat_index: latIndex,
    lng_index: lngIndex,
    direction: direction,
    daily_count: dailyCount ?? 0,
    latitude: latitude,
    longitude: longitude
  }
}
];

return [
{
  json: {
    lat_index: $json.lat_index,
    lng_index: $json.lng_index,
    direction: $json.direction,
    latitude: $json.latitude,
    longitude: $json.longitude
  }
}
];
